(7529051, 1203803, 173844, '<td valign="top">I like the contrasts of massive and delicate, out in the open and intimate.</td>', 'I like the contrasts of massive and delicate, out in the open and intimate.', '2017-08-15 18:44:41.000000', NULL, 1),
(7529052, 1203788, 173844, '<td valign="top">Strong sense of being impelled along the line of the river, even though much of it is hidden.  Very pretty scene.</td>', 'Strong sense of being impelled along the line of the river, even though much of it is hidden.  Very pretty scene.', '2017-08-15 18:47:39.000000', NULL, 1),
(7529053, 1203852, 173844, '<td valign="top">Very compelling image, so much so that I feel like I''m imposing.  The leading lines are brief but stark.</td>', 'Very compelling image, so much so that I feel like I''m imposing.  The leading lines are brief but stark.', '2017-08-15 18:50:37.000000', NULL, 1),
