(7529057, 1203843, 173844, '<td valign="top">Modest, well-balanced and appealing.</td>', 'Modest, well-balanced and appealing.', '2017-08-15 18:56:05.000000', NULL, 1),
(7529058, 1203802, 173844, '<td valign="top">Cleverly leads us in both directions, and so strongly from where we''ve come.  Kind of magical.</td>', 'Cleverly leads us in both directions, and so strongly from where we''ve come.  Kind of magical.', '2017-08-15 18:58:15.000000', NULL, 1),
(7529059, 1203471, 173844, '<td valign="top">Strong lines, simple composition and a compelling background.</td>', 'Strong lines, simple composition and a compelling background.', '2017-08-15 18:59:45.000000', NULL, 1),
(7529060, 1203837, 173844, '<td valign="top">Handsome treatment.  Leaves me anxious.</td>', 'Handsome treatment.  Leaves me anxious.', '2017-08-15 19:01:33.000000', NULL, 1),
