(7529131, 1203153, 68504, '<td valign="top">this is a wonder of light and perspective. and the man in the white suit. generous, grand.</td>', 'this is a wonder of light and perspective. and the man in the white suit. generous, grand.', '2017-08-16 01:52:14.000000', NULL, 0),
(7529133, 1203779, 68504, '<td valign="top">quite delightful in its clean simplicity. I think the leading lines are beautifully subtle, the curved path, the curved base of the lighthouse.</td>', 'quite delightful in its clean simplicity. I think the leading lines are beautifully subtle, the curved path, the curved base of the lighthouse.', '2017-08-16 01:55:20.000000', NULL, 0),
(7529134, 1203837, 68504, '<td valign="top">I love how at least 2 commenters have picked up on the angst, so well delivered by the grit and composition.</td>', 'I love how at least 2 commenters have picked up on the angst, so well delivered by the grit and composition.', '2017-08-16 01:57:43.000000', NULL, 0),
(7529135, 1203841, 68504, '<td valign="top">very well shown. we should view this constantly as a reminder of what we are.</td>', 'very well shown. we should view this constantly as a reminder of what we are.', '2017-08-16 02:00:34.000000', NULL, 0),
