(7529268, 1203773, 182284, '<td valign="top">Very nice shot. Congratulations on Front Page and Top Ten.</td>', 'Very nice shot. Congratulations on Front Page and Top Ten.', '2017-08-16 11:27:58.000000', NULL, 0),
(7529269, 1203824, 12611, '<td valign="top">I am more and more of the mind that although beautiful and rugged landscapes exist in abundance, the power of the presentation is tantamount, and you have acheived it here. Very Nice!</td>', 'I am more and more of the mind that although beautiful and rugged landscapes exist in abundance, the power of the presentation is tantamount, and you have acheived it here. Very Nice!', '2017-08-16 11:28:16.000000', NULL, 0),
